from questions._util import IX, ROADMAP, q

DOCKER_SEC = "https://labs.iximiuz.com/tutorials/docker-security-introduction-a859718d"
SECRETS = "https://labs.iximiuz.com/challenges/docker-build-using-secrets-private-go-module"

QUESTIONS = [
    q("srv-nginx", "medium", "Nginx is the public listener and the app is on 127.0.0.1:8080. What belongs in the server block?", "proxy_pass to the upstream, plus the headers the app needs for scheme and client address.", "A root directive only. proxy_pass is for Apache.", "The app's source code.", "A second listen on 8080 that publishes the app directly and ignores the proxy.", "Nginx terminates the public connection and proxies. The app does not have to be on a public interface."),
    q("srv-nginx", "medium", "A reload failed and the old workers are still serving. What does nginx -t buy you before the reload?", "It checks the config without replacing the running workers. A bad reload is how you drop traffic.", "It rotates logs.", "It upgrades the package.", "It flushes the upstream connections and cannot fail.", "Test, then reload. reload keeps the old workers if the new config does not load."),
    q("srv-nginx", "hard", "The upstream is healthy and Nginx returns 413. What is the knob?", "client_max_body_size. The body is larger than Nginx will read.", "worker_processes. That sets the body limit.", "keepalive_timeout, which is the body size.", "The TLS protocol list.", "413 is a client body the proxy refused. Raise the limit on purpose, not by accident on an upload endpoint you did not mean to open."),
    q("srv-nginx", "easy", "What is a worker process in Nginx?", "The process that handles connections. The master reads config and manages workers.", "A Kubernetes worker node.", "The access log.", "A CGI binary for every request.", "You scale workers with CPU. The master staying up is what makes a reload possible."),
    q("srv-apache", "medium", "You inherited an Apache server and a vhost is not the one you are hitting. What selects the vhost?", "The matching ServerName or ServerAlias for the Host header, after the listen address matches.", "The alphabetical order of files in /etc only, ignoring ServerName.", "The size of the access log.", "The first vhost is always used for every name, even when the names match another one. The first is only the default.", "Name-based hosting needs the name to match. The default vhost catches what does not."),
    q("srv-apache", "easy", "Apache and Nginx are both reasonable choices for which job?", "Serving static files and reverse-proxying to an application.", "Replacing the kernel firewall.", "Storing container images.", "Running etcd.", "They are HTTP servers and proxies. The rest of the platform does not care which one, as long as the config is the one you tested."),
    q("srv-apache", "medium", "A .htaccess file changed nothing. What is a common reason?", "AllowOverride is off for that directory, so Apache never reads .htaccess.", ".htaccess overrides the main config even when AllowOverride None.", "Apache reloads .htaccess only on reboot, and AllowOverride is irrelevant.", "The file must be named htaccess.conf in /etc.", "AllowOverride None is also how you stop a web root from changing auth rules out from under you."),
    q("srv-apache", "hard", "You are choosing between Nginx and Apache for a high-connection proxy. What is the actual decision?", "Which one your team can configure safely. Both can proxy. An unfamiliar rewrite language is an outage.", "Apache cannot proxy.", "Nginx cannot do TLS.", "The choice is fixed by the language of the application.", "Operability beats the benchmark you are not going to run."),
    q("srv-caddy", "medium", "Caddy's selling point on a small edge host is:", "It fetches and renews a public certificate for the site names with very little config.", "It replaces Kubernetes.", "It cannot terminate TLS.", "It only serves FTP.", "Automatic HTTPS is the feature. You still have to point DNS at the host and let it answer the challenge."),
    q("srv-caddy", "easy", "A Caddy site block with reverse_proxy is doing the same job as:", "Nginx proxy_pass.", "iptables MASQUERADE.", "A git remote.", "A Prometheus scrape.", "Both are reverse proxies. The syntax changes, the role does not."),
    q("srv-caddy", "medium", "Automatic HTTPS failed. What do you check before blaming the proxy code?", "DNS points at this host, port 80 or 443 is reachable for the challenge, and the hostname is one a public CA may sign.", "That the server has a GPU.", "That the app is written in Go.", "The inode of the access log.", "ACME needs a reachable name. An internal-only name needs an internal CA, not a public one."),
    q("srv-caddy", "hard", "Why would you still put Caddy behind a cloud load balancer?", "The balancer is the stable public address and the health check. Caddy is the HTTP config on the instance.", "You would not. Two proxies always break TLS.", "Caddy cannot run if any other proxy exists.", "Load balancers cannot pass TCP 443.", "Edges stack. Know which hop terminates TLS so you do not decrypt twice by accident."),
    q("srv-envoy", "medium", "In a service mesh, Envoy's usual job next to an app is:", "To be the sidecar that takes inbound and outbound traffic so policy, mTLS, and metrics happen outside the app.", "To replace the container runtime.", "To store the deployment YAML.", "To be the Kubernetes scheduler.", "The app talks to localhost or is redirected to the sidecar. The sidecar talks to the rest of the mesh."),
    q("srv-envoy", "medium", "A listener, a route, and a cluster in Envoy correspond to:", "Where it accepts connections, how it matches a request, and the upstream pool it sends to.", "Three kinds of TLS certificates.", "CPU, memory, and disk.", "Namespace, pod, and node.", "If the cluster has no healthy endpoints, the listener still accepts and then fails the request."),
    q("srv-envoy", "hard", "An eBPF program redirects connections into Envoy without the app knowing. What must the redirect avoid?", "A loop, where Envoy's own outbound connection is redirected back into Envoy.", "Using a socket.", "Reading packet headers.", "Running on Linux.", "The usual guard is a mark or an identity so the proxy's own flows are not captured again.", IX, "https://labs.iximiuz.com/tutorials/ebpf-envoy-egress-dc77ccd7"),
    q("srv-envoy", "easy", "Envoy is not unique to one mesh. What else uses it?", "Ingress controllers and API gateways. It is a proxy you can run on its own.", "Only Istio.", "Only as a text editor.", "Only on Windows desktops.", "Treat it as a programmable proxy. The control plane is what differs between products."),
    q("srv-cache", "medium", "A caching reverse proxy in front of an app helps when:", "Many clients fetch the same cacheable response and you can say so with freshness rules.", "Every response is a unique POST.", "You want to hide a memory leak in the app. The cache will not do that.", "The origin is faster than the cache.", "Cache what is safe to reuse. Authenticated and personalized responses need explicit rules or you will leak one user to another."),
    q("srv-cache", "easy", "What does a CDN cache that your origin used to serve?", "Copies of cacheable responses, closer to the client.", "Your git credentials.", "The origin's private keys, by default.", "TCP state for SSH.", "The origin still has to serve the first request and anything you mark uncacheable."),
    q("srv-cache", "medium", "You deployed a new asset and clients still see the old one. What is the lever?", "The cache key and the TTL or the invalidation. A new file at the same URL can be sitting in the cache.", "Restarting the laptop browser only. Shared caches ignore origin headers.", "Deleting the origin. Caches then invent a new file.", "Changing the TCP port of SSH.", "Name the asset with a hash, or purge. Otherwise the TTL is the wait."),
    q("srv-cache", "hard", "Why is caching a Set-Cookie response dangerous by default?", "The next client can receive the first client's cookie and session.", "Cookies disable TCP.", "Caches cannot store headers.", "Set-Cookie forces the origin offline.", "Default rules should treat cookie and authorization responses as private."),
    q("ctr-images", "medium", "A tag and a digest on the same image differ because:", "The tag moves. The digest names the exact bytes.", "The digest moves and the tag cannot.", "They are two hashes of the Dockerfile only, not the image.", "Tags are required to be immutable by the OCI spec. They are not.", "Pin production by digest if you need the same bytes tomorrow.", ROADMAP, "https://roadmap.sh/docker"),
    q("ctr-images", "medium", "An image is a stack of layers plus config. What does that buy a rebuild?", "Unchanged layers are reused. A change near the top does not resend the base.", "Every build uploads the base OS again, always.", "Layers are encrypted with the tag.", "A layer can be edited in place after it is pushed.", "Order the Dockerfile so the stable steps come first. The cache key is the instruction and its inputs."),
    q("ctr-images", "easy", "What is the writable layer of a running container?", "A thin layer on top of the image. It disappears with the container unless you commit it, which you should treat as a smell.", "A copy of the host's root filesystem.", "The registry.", "The Kubernetes etcd key for the pod.", "Put durable data in a volume. The container filesystem is not a disk you meant to keep."),
    q("ctr-images", "hard", "Two machines pull nginx:latest and run different code. How?", "The tag moved between the pulls, or the platforms resolved to different manifests.", "Images are built on pull from the Dockerfile in the registry. That is not how pull works.", "latest is a digest.", "The kernel recompiles the image.", "latest is a pointer. Record the digest you actually ran."),
    q("ctr-dockerfile", "medium", "Which instruction adds a new layer that later instructions can invalidate?", "RUN, COPY, and ADD. A changed COPY invalidates the steps after it.", "ENV, which always busts every layer including the ones before it.", "LABEL only.", "WORKDIR, which sends the image to the registry.", "Keep volatile COPY commands late so the dependency install stays cached."),
    q("ctr-dockerfile", "medium", "The process in the container is root and the Dockerfile never said USER. Why?", "The default user is root. A non-root user has to be created and selected.", "The default user is nobody.", "USER is implied by FROM.", "Root inside a container is not root. That is only true with a user namespace.", "Add a user and set USER. Otherwise you shipped root.", IX, DOCKER_SEC),
    q("ctr-dockerfile", "easy", "What does ENTRYPOINT versus CMD change when someone passes arguments to docker run?", "Arguments replace CMD. They are appended to ENTRYPOINT unless the entrypoint is also overridden.", "They replace both, always.", "They are ignored.", "They become environment variables automatically.", "Use ENTRYPOINT for the binary and CMD for default arguments if you want extra args to be natural."),
    q("ctr-dockerfile", "hard", "A shell form RUN pipes to another command and the build succeeds even when the first command fails. Why?", "The shell's default pipeline status is the last command. Enable pipefail in that RUN.", "Docker ignores exit codes.", "Pipes are not allowed in Dockerfiles, so this cannot happen.", "The first command never runs.", "RUN is a shell unless you use the exec form. The shell's rules apply, including pipeline status."),
    q("ctr-multistage", "medium", "Why is a multi-stage build smaller and safer than shipping the compiler in the runtime image?", "The final stage copies only the artifact. The toolchain and its vulnerabilities stay in the build stage.", "The final stage always includes every previous stage.", "Multi-stage disables layer caching.", "It encrypts the binary.", "Build tools are an attack surface and a size cost. Leave them behind."),
    q("ctr-multistage", "easy", "What does COPY --from=build /out/app /app do?", "It copies a path out of a named earlier stage into the current image.", "It copies from the host's /out.", "It starts a container named build.", "It pushes the image.", "The build stage can be a fat SDK image. The last stage can be distroless or a tiny base."),
    q("ctr-multistage", "medium", "A Go binary built in Alpine fails in a distroless or scratch image with a dynamic linker error. What happened?", "The binary is not static, and the runtime image has no libc or linker.", "scratch includes glibc.", "Go cannot be compiled statically.", "The error means the registry is down.", "Either build with the right static flags or use a runtime base that has the libraries you linked."),
    q("ctr-multistage", "hard", "You copied a CA bundle into the runtime stage and HTTPS calls still fail. What else is easy to forget?", "The application may expect the certs at a distro-specific path, or it may be using a copy you did not include.", "HTTPS does not use CA bundles.", "Multi-stage builds cannot copy files smaller than 1K.", "The scratch image updates CA bundles on boot.", "Know where that binary looks for trust. A file in the wrong directory is the same as a missing file."),
    q("ctr-registries", "medium", "docker pull and a later deploy disagree about the image. You used a tag. What should the deploy record?", "The digest the pull resolved to.", "The tag only. Digests are local.", "The Dockerfile line number.", "The container id, which is the same across hosts.", "The registry maps a tag to a digest at a moment in time. The digest is the identity."),
    q("ctr-registries", "medium", "A private registry pull works on your laptop and fails in the cluster with ImagePullBackOff. What does the cluster need?", "Credentials the node or the pod can use, typically an imagePullSecret, and a tag that exists there.", "Your laptop's docker login, which nodes inherit automatically.", "A public registry. Private registries cannot be pulled.", "The Dockerfile in the pod spec.", "The cluster does not share your ~/.docker/config.json."),
    q("ctr-registries", "easy", "What is a registry, as opposed to a repository?", "The registry is the service. A repository is a named image inside it, with tags.", "They are the same word.", "A repository is the running container.", "A registry is a Kubernetes Service type.", "ghcr.io is a registry. ghcr.io/org/app is a repository."),
    q("ctr-registries", "hard", "You copied an image to an air-gapped registry and the signature no longer verifies. Why might that be?", "The signature refers to the digest in the original registry, or you copied a tag and not the signed manifest.", "Signatures travel inside the layer tar and cannot be separated.", "Air-gapped registries rewrite every digest on purpose, always.", "Verification does not use the digest.", "Copy the manifest you signed, and re-check the digest on the far side. A retag can point at something else."),
    q("ctr-volumes", "medium", "A container writes to /data and the writes are gone after a recreate. There was no volume. Why?", "The writable layer is tied to that container. A new container gets a new layer from the image.", "Images are edited in place by container writes.", "Docker persists every directory under /data by default.", "The registry stores container writes.", "Mount a volume at /data if the bytes need to outlive the container."),
    q("ctr-volumes", "medium", "A bind mount of a host directory and a named volume differ because:", "The bind mount is a host path you manage. The named volume is Docker's directory, easier to move with the daemon and less obvious to back up.", "They are stored in the image.", "Named volumes cannot be read.", "Bind mounts work only on macOS.", "Know which one you are debugging. A bind mount shows host permissions. A named volume hides in the Docker data root."),
    q("ctr-volumes", "hard", "The app in the container cannot write the bind-mounted directory. The directory is 755 root:root. What is the mismatch?", "The container's user is not root and not the owner. Namespaces may also map the UID.", "Bind mounts ignore permissions.", "755 means world writable.", "The kernel remounts bind mounts as noexec always.", "Align the UID or the mode. Rootless and user namespaces make the host UID and the container UID different numbers."),
    q("ctr-volumes", "easy", "What does a tmpfs mount give a container?", "A memory filesystem that vanishes when the container stops.", "A disk snapshot.", "A registry mirror.", "A second network namespace.", "Use it for secrets you do not want on disk, knowing a crash dump or a process listing can still leak them."),
    q("ctr-networks", "medium", "Two containers on the default bridge cannot reach each other by container name, and two on a user-defined bridge can. Why the difference?", "User-defined bridges get DNS for container names. The default bridge does not.", "The default bridge disables IP.", "Names only work on the host network.", "DNS for containers requires Kubernetes.", "Put cooperating containers on a network you created. Do not rely on the default bridge for service discovery."),
    q("ctr-networks", "medium", "A container cannot reach a service bound to 127.0.0.1 on the host. Why?", "127.0.0.1 inside the container is the container, not the host. The host's loopback is a different network namespace.", "Docker blocks every connection to the host.", "Localhost is routed to the registry.", "The host firewall does not apply to 127.0.0.1, so this cannot be a bind issue.", "Publish the service on an address the container's network can route to, or run the client in the host namespace on purpose.", IX, "https://labs.iximiuz.com/challenges/docker-networking-reach-host-service-bound-to-localhost"),
    q("ctr-networks", "hard", "host network mode removes which isolation?", "The container shares the host's network namespace. It sees the host's interfaces and ports.", "The container gets its own kernel.", "It disables the filesystem.", "It encrypts all traffic.", "Use it deliberately. Port clashes and a missing network boundary are the cost."),
    q("ctr-networks", "easy", "What is the veth pair's role in bridge networking?", "One end is in the container namespace and the other is plugged into the bridge on the host.", "It is a TLS certificate.", "It replaces the default route on the laptop.", "It stores image layers.", "That pair is the cable between the container and docker0."),
    q("ctr-ports", "medium", "docker run -p 127.0.0.1:8080:80 does what a bare -p 8080:80 does not?", "It publishes the container port only on the host's loopback, so other machines cannot open it.", "It publishes on every interface, including the public one. That is the bare form.", "It disables the port.", "It requires host networking.", "Bind the address on purpose. The default publish is a wide listen."),
    q("ctr-ports", "medium", "Several dev servers need the same container port and must run together. What avoids the clash?", "Publish the container port on an ephemeral host port, or on different host ports, and discover the mapping.", "They cannot run on one host.", "Use the same host port twice. Docker will load balance.", "Disable the bridge.", "docker port or the inspect output tells you where each one landed.", IX, "https://labs.iximiuz.com/challenges/docker-101-container-publish-random-port"),
    q("ctr-ports", "hard", "You published a port on the internal IP only, and it is still reachable from the external network. Why is that a firewall problem and not a Docker bind problem?", "Docker's NAT and filter rules can accept the traffic in a chain your host policy does not see first.", "Published ports are Unix sockets and ignore addresses.", "Linux cannot have two NICs.", "The internal IP is always public.", "Look at DOCKER-USER and the ingress interface, not only at the -p address.", IX, "https://labs.iximiuz.com/challenges/docker-networking-prevent-unexpected-access-to-published-port"),
    q("ctr-ports", "easy", "EXPOSE in a Dockerfile does what at runtime by itself?", "It documents the port. It does not publish it on the host.", "It is identical to -p.", "It opens the port on the public internet.", "It creates a Service.", "Publish is a run or compose decision."),
    q("ctr-compose", "medium", "depends_on without a health check condition means:", "Compose starts the dependency first. It does not wait until the dependency can serve.", "The app waits until the dependency's port answers.", "The dependency is restarted when the app exits.", "The networks are not created.", "Add a healthcheck and a condition if the race matters. A database process existing is not a database accepting connections."),
    q("ctr-compose", "easy", "What file is the usual Compose definition?", "compose.yaml or docker-compose.yml in the project directory.", "Dockerfile only.", "The Kubernetes manifest. Compose cannot have its own file.", "/etc/shadow.", "The Dockerfile builds images. Compose runs the set."),
    q("ctr-compose", "medium", "A compose service name is useful on the project network because:", "Other services can resolve it as a DNS name.", "It becomes the image tag in every registry.", "It disables the bridge.", "It is the Linux username.", "The name is the internal hostname. Do not hard-code container IPs."),
    q("ctr-compose", "hard", "You changed a build argument and compose up did not rebuild. What do you add?", "A build, or up --build. Compose will reuse an existing image when it thinks nothing relevant changed.", "down -v, which only removes volumes and always rebuilds.", "A reboot.", "There is no way to rebuild.", "Be explicit when the cache or the image name is lying to you."),
    q("ctr-runtime", "medium", "dockerd, containerd, and runc divide the work as:", "dockerd is the API you talk to, containerd supervises containers, and runc is the OCI runtime that creates the process.", "runc is the registry.", "containerd is a Dockerfile linter.", "They are three names for the same binary.", "A container is still a process. The stack is who sets up the namespaces and keeps the shim.", IX, DOCKER_SEC),
    q("ctr-runtime", "medium", "crictl and docker see different containers on a Kubernetes node. Why?", "Kubernetes talks to the CRI runtime, often containerd. docker talks to dockerd. They are different inventories unless one is driving the other.", "crictl shows images only.", "The kubelet uses Docker's socket on every modern cluster.", "crictl is a log viewer.", "Debug cluster containers with the CRI tool. docker ps can be an empty lie on a containerd node.", IX, "https://labs.iximiuz.com/courses/containerd-cli"),
    q("ctr-runtime", "easy", "What is the OCI runtime spec about?", "How a runtime creates a container process from a bundle: config plus rootfs.", "How to write a Dockerfile.", "The Kubernetes API.", "TLS ciphers.", "runc implements that spec. Other runtimes can too."),
    q("ctr-runtime", "hard", "A Kata or other VM-based runtime is chosen over runc when:", "You want a guest kernel boundary, not only namespaces on the host kernel.", "You want faster startup than any namespace runtime and no isolation.", "You need to share the host kernel's memory pages on purpose.", "The CVE class you care about is only application logic.", "Namespace escapes are host-kernel bugs. A separate kernel changes that trade."),
    q("ctr-security", "medium", "The Docker socket is mode 660 root:docker. What did you grant the docker group?", "Full control of the daemon, which is enough to become root on the host.", "Read-only access to container logs.", "Permission to run rootless containers only.", "Nothing, because the daemon authorizes each API call by default. It does not.", "There is no authorization plugin in a default install. The socket is the authorization.", IX, DOCKER_SEC),
    q("ctr-security", "hard", "Which published daemon port is the unsafe one, and why?", "2375, because it is plain TCP with no client auth. 2376 is the TLS port.", "2376, because TLS is weaker than an open port.", "22, which is the daemon API.", "Neither. Both require a client certificate by default.", "An open 2375 on a network is a remote root shell. Prefer SSH to the host over exposing the API.", IX, DOCKER_SEC),
    q("ctr-security", "hard", "docker run --privileged --pid=host --net=host -v /:/host is a breakout because:", "It removes the isolation and mounts the host root in a place the container can chroot into.", "Privileged only adds a GPU.", "The host mount is read-only unless you pass a second flag. It is not.", "PID host hides the host processes.", "Anyone who can pass those flags is an administrator. Do not give them the socket.", IX, DOCKER_SEC),
    q("ctr-security", "medium", "Mounting /var/run/docker.sock into a container is:", "The same power as the docker group, from inside the container. It is a breakout path.", "A supported way to give a container read-only metrics with no risk.", "Required for every build.", "Blocked by the default seccomp profile.", "A CI helper that mounts the socket is a root shell that happens to live in a container.", IX, DOCKER_SEC),
    q("ctr-secrets", "medium", "A private module must be fetched during docker build. The token is in an ARG. What is wrong?", "ARG values leak into image history and cache. A build secret mount is the mechanism that does not bake the token into a layer.", "ARG values are deleted from the image automatically and never appear in history.", "Secrets cannot be used at build time at all.", "The token should be COMMITTED into the Dockerfile.", "Use BuildKit --mount=type=secret or the equivalent. Do not leave the credential in a layer.", IX, SECRETS),
    q("ctr-secrets", "hard", "The secret mount is available in one RUN and gone in the next. Is that a bug?", "No. The mount lasts for that instruction so the secret is not copied into the filesystem you commit.", "Yes. Secrets should persist in the final image so the app can rebuild itself.", "The mount writes the secret into the layer metadata on purpose.", "RUN cannot see mounts.", "Fetch what you need while the mount is there. The final image should run without the build token.", IX, SECRETS),
    q("ctr-secrets", "easy", "Where should a runtime database password live, relative to the image?", "Outside the image: a secret store, a Kubernetes Secret, or a file mounted at start. Not in ENV of the Dockerfile.", "In the Dockerfile ENV, so it is versioned.", "In the image label.", "In the public registry description.", "Images get copied. Treat them as public even when the registry is private."),
    q("ctr-secrets", "medium", "A multi-stage build copied a .netrc into the runtime stage by habit. What did you ship?", "The credentials. The runtime stage is the image you run.", "Nothing. Later stages cannot copy dotfiles.", ".netrc is ignored by COPY.", "Only the username. Tokens are stripped.", "Copy the artifact, not the home directory of the build."),
    q("ctr-containerd", "medium", "On a containerd node, which CLI talks the same API the kubelet uses?", "crictl, via the CRI socket. ctr talks containerd's own API and can show a different view.", "docker, always.", "kubectl exec, which lists images.", "systemctl, which is the CRI.", "Use the CRI tool when the question is 'what the kubelet sees'."),
    q("ctr-containerd", "easy", "nerdctl exists because:", "People want a Docker-like CLI aimed at containerd.", "Kubernetes removed containers.", "It is the OCI runtime that replaces runc.", "It stores images in git.", "It is a client. containerd is still the daemon."),
    q("ctr-containerd", "medium", "A pod is Running in kubectl and crictl ps shows no such container. What should you suspect?", "You are on the wrong node, the wrong namespace in the runtime, or you are querying a different socket than the kubelet.", "kubectl invents pods that have no processes.", "crictl cannot see Running pods.", "The container is a kernel thread and has no id.", "The runtime is local to the node. Point the tool at the socket the kubelet uses, on the node that actually runs the pod."),
    q("ctr-containerd", "hard", "Why can ctr and crictl disagree about namespaces?", "containerd has its own namespaces, and the CRI plugin uses one of them. A default ctr invocation may be looking at another.", "They share one flat list and cannot disagree.", "crictl shows host processes.", "Namespaces were removed in cgroup v2.", "Pass the k8s namespace when you use ctr, or prefer crictl for cluster debugging."),
    q("ctr-rootless", "medium", "Rootless Docker runs the daemon as a normal user. A container that thinks it is root shows up on the host as:", "That normal user, because user namespaces map container UID 0 to the user's UID.", "UID 0 on the host. Rootless does not change that.", "nobody, always, with no mapping.", "The docker group, which is still host root.", "id inside says root. ps outside says the unprivileged account. That is the point.", IX, DOCKER_SEC),
    q("ctr-rootless", "hard", "What host package does rootless mode need so the user can allocate subordinate UIDs?", "uidmap, so newuidmap can set up the user namespace range.", "nfs-kernel-server.", "A public IP.", "The Docker socket left at mode 666. That is the opposite of the goal.", "Without a subordinate UID range the mapping cannot be installed.", IX, DOCKER_SEC),
    q("ctr-rootless", "medium", "Rootless mode does not make a privileged container safe to hand to strangers. What is still true?", "The user who owns the daemon can still harm everything that user can harm, including their files and their other containers.", "Rootless means the process has no permissions on the host at all.", "User namespaces disable volume mounts.", "It replaces image scanning.", "It shrinks the blast radius from host root to that user. It is not a sandbox for untrusted code by itself."),
    q("ctr-rootless", "easy", "Why prefer rootless or a rootless runtime for a developer daemon on a laptop?", "A compromise of the socket is no longer instant host root.", "It makes containers faster than processes.", "It disables networking.", "It removes the need for images.", "The daemon is the trust boundary. Do not run it as root if you do not need to.", IX, DOCKER_SEC),
    q("ctr-debug", "medium", "A distroless container has no shell and you need to see a file. What is the Kubernetes-shaped answer?", "An ephemeral debug container that shares the pod's namespaces, via kubectl debug, instead of assuming kubectl exec has a shell.", "Rebuild the image with bash and redeploy to production as the fix.", "The file is on the host at the same path.", "nsenter cannot attach to a container.", "exec only works if the image has the binary. A debug container brings the tools with it.", IX, "https://labs.iximiuz.com/skill-paths/master-kubectl-debug"),
    q("ctr-debug", "medium", "The process is running and you want its view of the mounts without restarting it. What do you read?", "/proc/<pid>/mountinfo, from the host or from a namespace that can see that pid.", "The Dockerfile.", "The registry manifest. It lists live mounts.", "dmesg only.", "The live mount table is in proc. The image history will not mention a volume added at run time."),
    q("ctr-debug", "hard", "A container can resolve DNS and cannot open TCP to one address. Where do you split the fault?", "DNS worked, so compare a route and a filter and a connect from inside the same network namespace.", "DNS success proves every port is open.", "Restart the registry.", "The image tag is the only cause of a TCP timeout.", "Use the container's netns: ip route, a connect to the IP, and a capture. Do not confuse name lookup with reachability."),
    q("ctr-debug", "easy", "docker logs shows nothing and the app is quiet. What else carries output?", "A file the process writes, which may be on a volume or only inside the writable layer, and the supervisor if one wraps the process.", "Only the registry.", "The Kubernetes scheduler log, for every app log.", "BIOS.", "stdout is a choice the process makes. Many servers log to a file instead."),
]
